    private static readonly byte[] Comp = BuildCompTable();

    public static void Main(string[] args)
    {
        using var input = Console.OpenStandardInput();
        using var output = Console.OpenStandardOutput();

        var reader = new BufferedReader(input);
        var writer = new BufferedWriter(output);

        string? header = null;
        byte[] seq = new byte[1024];
        int len = 0;

        while (true)
        {
            string? line = reader.ReadLine();
            if (line == null)
            {
                if (header != null)
                    WriteRecord(writer, header, seq, len);
                break;
            }

            if (line.Length > 0 && line[0] == '>')
            {
                if (header != null)
                    WriteRecord(writer, header, seq, len);

                header = line;
                len = 0;
            }
            else
            {
                int needed = len + line.Length;
                if (needed > seq.Length)
                {
                    int newSize = seq.Length;
                    while (newSize < needed) newSize <<= 1;
                    Array.Resize(ref seq, newSize);
                }

                for (int i = 0; i < line.Length; i++)
                {
                    char c = line[i];
                    if (c == '\r' || c == '\n' || char.IsWhiteSpace(c)) continue;
                    seq[len++] = (byte)c;
                }
            }
        }

        writer.Flush();
    }

    private static void WriteRecord(BufferedWriter writer, string header, byte[] seq, int len)
    {
        writer.WriteLine(header);

        const int wrap = 60;
        int outLen = len;
        for (int i = outLen - 1; i >= 0; i -= wrap)
        {
            int start = i - wrap + 1;
            if (start < 0) start = 0;
            int count = i - start + 1;

            char[] line = new char[count];
            int p = 0;
            for (int j = i; j >= start; j--)
                line[p++] = (char)Comp[seq[j]];
            writer.WriteLine(line);
        }
    }

    private static byte[] BuildCompTable()
    {
        var t = new byte[256];
        for (int i = 0; i < 256; i++) t[i] = (byte)i;

        void map(char a, char b)
        {
            t[(byte)a] = (byte)b;
            t[(byte)char.ToLowerInvariant(a)] = (byte)char.ToLowerInvariant(b);
        }

