        map('C', 'G');
        map('G', 'C');
        map('T', 'A');
        map('U', 'A');

        map('M', 'K');
        map('R', 'Y');
        map('W', 'W');
        map('S', 'S');
        map('Y', 'R');
        map('K', 'M');

        map('V', 'B');
        map('H', 'D');
        map('D', 'H');
        map('B', 'V');

        map('N', 'N');
        map('X', 'X');
        map('I', 'I');

        return t;
    }

