                if (b == (byte)'\n') return sb.ToString();
                if (b == (byte)'\r')
                {
                    if (_pos >= _len)
                    {
                        _len = _stream.Read(_buf, 0, _buf.Length);
                        _pos = 0;
                    }
                    if (_len > 0 && _buf[_pos] == (byte)'\n') _pos++;
                    return sb.ToString();
                }

                sb.Append((char)b);
            }
        }
    }

