        public void WriteLine(string s)
        {
            Write(s);
            WriteByte((byte)'\n');
        }

        public void WriteLine(char[] chars)
        {
            Write(chars);
            WriteByte((byte)'\n');
        }

        public void Write(string s)
        {
            int n = s.Length;
            for (int i = 0; i < n; i++) WriteByte((byte)s[i]);
        }

        public void Write(char[] chars)
        {
            for (int i = 0; i < chars.Length; i++) WriteByte((byte)chars[i]);
        }

        private void WriteByte(byte b)
        {
            if (_pos >= _buf.Length) Flush();
            _buf[_pos++] = b;
        }

        public void Flush()
        {
            if (_pos > 0)
            {
                _stream.Write(_buf, 0, _pos);
                _pos = 0;
            }
            _stream.Flush();
        }

        public void Dispose() => Flush();
    }
